package dev.zomboid.clans;
import java.util.*;import net.minecraft.core.*;import net.minecraft.server.*;import net.minecraft.resources.*;import net.minecraft.world.item.*;import me.danialisntcool.factionfriction.faction.*;
public class NexusUpgradeChecks {
 static int checks;static void ok(boolean b,String msg){checks++;if(!b)throw new AssertionError(msg);}
 public record Fluid(){public boolean isEmpty(){return true;}}
 public record SurfaceState(boolean solid){public boolean isSolidRender(Object world,Object pos){return solid;}public Fluid getFluidState(){return new Fluid();}}
 public static class SurfaceWorld extends PveChecks.World {int born,particles,hums;public void sendParticles(Object options,double x,double y,double z,int count,double dx,double dy,double dz,double speed){particles++;}public void playSound(Object player,Object pos,Object sound,Object source,float volume,float pitch){hums++;}SurfaceWorld(MinecraftServer s){super(s);}public int getHeight(Object type,int x,int z){return x>10?90:65;}public boolean canSeeSky(Object pos){return ((BlockPos)pos).getY()>=65;}public Object getBlockState(Object value){BlockPos pos=(BlockPos)value;if(pos.equals(nexus))return new PveChecks.State(Nexus.BLOCK);return new SurfaceState(pos.getY()==64||pos.getY()==89);}public boolean noCollision(Object mob){return true;}public boolean addFreshEntity(Object value){PveChecks.Mob mob=(PveChecks.Mob)value;entities.put(mob.id,mob);born++;return true;}}
 public static class Defender extends PveChecks.Player {Defender(MinecraftServer s,PveChecks.World w){super(s,w);}public int notices;public Object lastSound;public void playNotifySound(Object sound,Object source,float volume,float pitch){notices++;lastSound=sound;}public double distanceToSqr(double x,double y,double z){return 10000;}}
 public static class Graphics {Object icon;public void renderItem(Object stack,int x,int y){icon=stack;}}
 public static void main(String[]args){MinecraftServer server=new MinecraftServer();SurfaceWorld world=new SurfaceWorld(server);Defender p=new Defender(server,world);Faction faction=new Faction("Test");faction.members.put(p.uuid,FactionRank.CREATOR);server.manager.factions.put(faction.id,faction);Clans.bind(server.manager,server);ClanState.Profile profile=Clans.state(server.manager).profile(faction.id);profile.nexusPlaced=true;profile.nexusPos=world.nexus.asLong();Pve.Wave w=new Pve.Wave(faction.id,world,0,0,0);w.health=w.displayHealth=100;w.participants.add(p.uuid);Pve.waves.put(faction.id,w);SurfaceSpawns.refresh(w,world.nexus);ok(!w.surface.isEmpty(),"surface candidates found");ok(w.surface.stream().allMatch(spot->spot[1]==65),"high roof candidates removed in favor of low exterior ground");ok(w.surface.stream().noneMatch(spot->spot[1]<65),"basement heights never sampled");ok(Pve.spawn(w,p)&&world.born==1&&w.alive==1&&w.pending==11,"actual production spawn creates an enemy");PveChecks.Mob mob=world.entities.values().iterator().next();ok(!mob.noAi&&mob.nav.moves>0,"AI enabled and navigation started immediately");ok(mob.y==65&&mob.glowing,"spawned enemy on first exterior floor with outline");
 int moves=mob.nav.moves;w.pending=0;server.time=20;Pve.tick(server);ok(mob.nav.moves>moves,"server wave heartbeat restarts navigation");com.tacz.guns.api.TimelessAPI.guns.put(ResourceLocation.parse("tacz:glock"),new com.tacz.guns.api.TimelessAPI.Index("pistol",new com.tacz.guns.api.TimelessAPI.Data(ResourceLocation.parse("tacz:9mm"))));com.tacz.guns.api.TimelessAPI.guns.put(ResourceLocation.parse("fracturepoint:rifle"),new com.tacz.guns.api.TimelessAPI.Index("rifle",new com.tacz.guns.api.TimelessAPI.Data(ResourceLocation.parse("fracturepoint:556"))));ok(Rewards.guns().size()==1&&Rewards.guns().get(0).id().startsWith("fracturepoint:"),"installed FracturePoint gun pack preferred");net.minecraft.core.registries.BuiltInRegistries.Registry.modKeys.addAll(Set.of("fracturepoint:nato_helmet","fracturepoint:nato_shturmovik_chestplate","fracturepoint:ratnik_leggings","fracturepoint:ratnik_boots","fracturepoint:ceramic_plate_level_iv"));Rewards.improve(profile,2);ok(profile.rewards.containsKey("gun@fracturepoint:rifle")&&profile.rewards.get("ammo@fracturepoint:556")==96,"weapon and compatible ammo deposited");ok(profile.rewards.containsKey("fracturepoint:nato_helmet")&&profile.rewards.containsKey("fracturepoint:ratnik_boots"),"registered armor deposited");ItemStack gun=(ItemStack)Rewards.stack("gun@fracturepoint:rifle",1);ok(gun.gunId.equals("fracturepoint:rifle")&&gun.rounds==0&&!gun.chambered&&gun.mode.equals("SEMI"),"gun stack has real gun ID and mode");ItemStack ammo=(ItemStack)Rewards.stack("ammo@fracturepoint:556",32);ok(ammo.ammoId.equals("fracturepoint:556")&&ammo.count==32,"ammo stack carries caliber component");ok(((ItemStack)Rewards.stack("gun@missing:gun",1)).count==0,"missing gun pack leaves reward pending");Graphics g=new Graphics();Rewards.icon(g,"gun@fracturepoint:rifle",10,10);ok(g.icon instanceof ItemStack&&((ItemStack)g.icon).gunId.equals("fracturepoint:rifle"),"deposit renders actual gun stack icon");ok(Rewards.name("gun@fracturepoint:rifle").equals("fracturepoint:rifle"),"deposit uses stack display name");PveChecks.Register soundRegister=new PveChecks.Register(net.minecraft.core.registries.Registries.SOUND_EVENT);Nexus.register(soundRegister);ok(soundRegister.values.size()==8,"eight registered event and generator sounds");w.displayHealth=100;w.health=80;Effects.tick(w);ok(world.particles==2&&world.hums==1,"smoke sparks and generator audio emitted");ok(p.notices==1,"nexus hit alert reaches defender");dev.zomboid.clans.ClanPacket packet=me.danialisntcool.factionfriction.network.FFNetwork.snapshots.getLast();ok(packet.action()==11&&packet.a().startsWith("80|100|20|"),"HUD packet includes health maximum and accumulated damage");server.time=40;Effects.tick(w);ok(world.hums==1&&p.notices==1,"generator and damage cues do not spam between intervals");server.time=100;Effects.tick(w);ok(world.hums==2,"generator continues while wave active");Effects.announce(w,"phase");ok(p.notices==2,"phase change cue plays");Effects.finish(w,false);ok(p.notices==3&&p.lastSound.toString().contains("defeat"),"defeat has distinct cue");NexusHud.accept("80|100|20|2|");ok(NexusHud.hp==80&&NexusHud.damage==20&&NexusHud.phase==2&&NexusHud.flash>System.nanoTime(),"client remembers damage flash and large HUD values");long flash=NexusHud.flash;NexusHud.accept("80|100|0|2|");ok(NexusHud.flash==flash,"next status packet preserves damage alert duration");System.out.println("PASS "+checks+" exterior spawn and equipment checks (API doubles)");}
}
